"""Derive the URDF used in simulation from the vendor URDF.

The vendor file is kept unmodified. Two things in it are wrong for physics
simulation, and this module corrects them in a generated copy:

* Every joint is limited to a full turn either way. The generated file carries
  the limits from ``understudy.arm``.
* ``end_effector_link`` is a marker with no mass. A physics engine gives a
  massless body a default mass (1 kg in PhysX, about twice the whole arm), so
  the generated file gives it a negligible one.
* Each gripper finger is a thin curved claw, and a physics engine collides with
  the convex hull of a mesh, which fills the hollow the two claws close around.
  The generated file gives each finger several convex pieces instead.

Regenerate with ``python -m understudy.sim_urdf`` after changing limits.
"""

from __future__ import annotations

import xml.etree.ElementTree as ET
from pathlib import Path

from . import arm
from .kinematics import DEFAULT_URDF

GENERATED = Path(__file__).resolve().parent.parent / "assets" / "generated"
SIM_URDF = GENERATED / "omx_f_sim.urdf"

# The fingers' collision shapes, as convex pieces that keep the hollow between the claws.
# scripts/build_finger_collision.py writes the files; the URDF below refers to them.
FINGER_COLLISION_DIR = GENERATED / "collision"
FINGER_MESHES = {1: "follower_07_gripper_motorized.stl", 2: "follower_08_gripper_gear.stl"}
FINGER_LINKS = {1: "link6", 2: "link7"}
FINGER_SLABS = 8
GENERATED_PACKAGE = "understudy_generated"


def finger_collision_files(finger: int) -> list[Path]:
    """Collision pieces of one finger, in order from the pivot to the tip."""
    return [FINGER_COLLISION_DIR / f"finger_{finger}_{k}.stl" for k in range(FINGER_SLABS)]

MARKER_MASS_KG = 1.0e-4
MARKER_INERTIA = 1.0e-9

_HEADER = """<?xml version="1.0" ?>
<!-- Generated by understudy/sim_urdf.py. Do not edit by hand.
     Derived from open_manipulator_description/urdf/omx_f/omx_f.urdf
     (ROBOTIS, Apache License 2.0). Changes from the original:
     joint limits narrowed to the limits in understudy/arm.py, a
     negligible mass added to links that had none, and each gripper
     finger's collision mesh replaced by convex pieces that keep its shape. -->
"""


def build(source_text: str) -> str:
    if "<!DOCTYPE" in source_text or "<!ENTITY" in source_text:
        raise ValueError("document type and entity declarations are not accepted")
    root = ET.fromstring(source_text)

    limits = {j.name: (j.lower, j.upper) for j in arm.ARM_JOINTS}
    limits.update(arm.GRIPPER_LIMITS)
    seen = set()
    for joint in root.findall("joint"):
        name = joint.get("name", "")
        if name not in limits:
            continue
        limit = joint.find("limit")
        if limit is None:
            raise ValueError(f"joint {name!r} has no <limit> element")
        lower, upper = limits[name]
        limit.set("lower", repr(lower))
        limit.set("upper", repr(upper))
        seen.add(name)
    missing = set(limits) - seen
    if missing:
        raise ValueError(f"joints not found in the URDF: {sorted(missing)}")

    children = {joint.find("child").get("link") for joint in root.findall("joint")}  # type: ignore[union-attr]
    for link in root.findall("link"):
        # The root link is welded to the world and needs no mass.
        if link.find("inertial") is not None or link.get("name") not in children:
            continue
        inertial = ET.SubElement(link, "inertial")
        ET.SubElement(inertial, "origin", xyz="0 0 0")
        ET.SubElement(inertial, "mass", value=repr(MARKER_MASS_KG))
        value = repr(MARKER_INERTIA)
        ET.SubElement(inertial, "inertia", ixx=value, ixy="0", ixz="0", iyy=value, iyz="0", izz=value)

    for finger, link_name in FINGER_LINKS.items():
        link = next((link for link in root.findall("link") if link.get("name") == link_name), None)
        if link is None:
            raise ValueError(f"finger link {link_name!r} not found in the URDF")
        for collision in link.findall("collision"):
            link.remove(collision)
        for piece in finger_collision_files(finger):
            collision = ET.SubElement(link, "collision")
            ET.SubElement(collision, "origin", rpy="0 0 0", xyz="0 0 0")
            geometry = ET.SubElement(collision, "geometry")
            ET.SubElement(geometry, "mesh", filename=f"package://{GENERATED_PACKAGE}/collision/{piece.name}")

    ET.indent(root, space="  ")
    return _HEADER + ET.tostring(root, encoding="unicode") + "\n"


def generate(source: Path = DEFAULT_URDF, destination: Path = SIM_URDF) -> Path:
    destination.parent.mkdir(parents=True, exist_ok=True)
    destination.write_text(build(source.read_text()))
    return destination


if __name__ == "__main__":
    print(generate())
